import type { AuthIR, SpecIR } from "@smithable/core";
import { humanize } from "@smithable/core";

const HEADER =
  "// Generated by Smithable from smithable.auth.yml. Do not edit: this file is overwritten on every change.\n";

/** Kit files that only apps with sign-in need. */
export const SIGN_IN_KIT = [
  "src/kit/SignIn.tsx",
  "src/lib/auth-client.ts",
  "src/routes/api/auth/$.ts",
];

export const hasSignIn = (auth: AuthIR) => auth.signIn !== "none";

const ENV: Record<string, [string, string]> = {
  google: ["GOOGLE_CLIENT_ID", "GOOGLE_CLIENT_SECRET"],
  facebook: ["FACEBOOK_CLIENT_ID", "FACEBOOK_CLIENT_SECRET"],
};

/** Development users get an address in an allowed domain, so they pass the sign-up check. */
export function devDomain(auth: AuthIR): string {
  return (auth.signIn === "none" ? undefined : auth.signIn.allowedDomains?.[0]) ?? "example.com";
}

/** The app invites people when it has a users page (which closed sign-up requires). */
export function hasInvitations(ir: SpecIR, auth: AuthIR): boolean {
  return hasSignIn(auth) && ir.pages.some((p) => p.pattern.kind === "users");
}

/** The roles as the app names them. */
export function roleLabels(auth: AuthIR): Record<string, string> {
  return Object.fromEntries(auth.roles.map((r) => [r.name, humanize(r.name)]));
}

/** A record of role names (identifiers) to texts, as code. */
const record = (o: Record<string, string>) =>
  `{ ${Object.entries(o)
    .map(([k, v]) => `${k}: ${JSON.stringify(v)}`)
    .join(", ")} }`;

/** Better Auth's configuration: providers, the Drizzle tables, roles and sign-up rules. */
export function authModule(auth: AuthIR, ir: SpecIR): string {
  if (auth.signIn === "none") throw new Error("No sign-in");
  const { providers, allowedDomains, selfSignUp } = auth.signIn;
  const invitations = hasInvitations(ir, auth);
  const defaultRole = JSON.stringify(auth.defaultRole);
  const provider = (name: string) => {
    const [id, secret] = ENV[name] as [string, string];
    const hd =
      name === "google" && allowedDomains?.length === 1
        ? `, hd: ${JSON.stringify(allowedDomains[0])}`
        : "";
    return `  ...(process.env.${id} && process.env.${secret}
    ? { ${name}: { clientId: process.env.${id}, clientSecret: process.env.${secret}${hd} } }
    : {}),`;
  };
  const email = providers.includes("email");
  const domainCheck = allowedDomains
    ? `
  if (!ALLOWED_DOMAINS.includes(email.split("@")[1] ?? ""))
    return \`Only \${ALLOWED_DOMAINS.join(" and ")} accounts can sign in.\`;`
    : "";
  // Who gets in: an invitation gives its role; closed sign-up refuses everyone else but the
  // admins (and, in development, the development users).
  const closed = invitations && !selfSignUp;
  const invitationCheck = closed
    ? `
  const invited = invitationOf(email);
  if (
    !(invited && invited.expiresAt.getTime() > Date.now()) &&
    !ADMINS.includes(email) &&
    !(import.meta.env.DEV && email.startsWith("dev-")) &&
    !(demoSignIn && email.startsWith("demo-"))
  )
    return invited
      ? "Your invitation has expired. Ask an administrator for a new one."
      : \`Only invited people can sign in to \${APP_NAME}. Ask an administrator for an invitation.\`;`
    : "";
  const refuses = Boolean(domainCheck || invitationCheck);
  const role = invitations ? `openInvitation(email)?.role ?? ${defaultRole}` : defaultRole;
  // A new account is in the audit log, and so is the invitation it used up.
  const afterCreate = `
        after: async (created) => {
          const who = { id: created.id, role: String(created.role) };${
            invitations
              ? `
          const email = created.email.toLowerCase();
          // Only an invitation still open was accepted (under open sign-up an expired one is not).
          const used = openInvitation(email);
          if (used)
            audit(db, who, { action: "invitation accepted", model: "User", details: { role: used.role } });
          // The invitation is used up: the user is the record from now on.
          db.delete(invitation).where(eq(invitation.email, email)).run();`
              : ""
          }
          audit(db, who, { action: "account created", model: "User", details: { role: who.role } });
        },`;
  const tables = invitations
    ? "account, invitation, session, user, verification"
    : "account, session, user, verification";
  return `${HEADER}import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
${refuses ? 'import { APIError } from "better-auth/api";\n' : ""}${email ? 'import { emailOTP } from "better-auth/plugins";\n' : ""}import { tanstackStartCookies } from "better-auth/tanstack-start";
import { eq } from "drizzle-orm";
import { db } from "#/db";
import { ${tables} } from "#/db/schema";
import { ADDRESS_HEADER } from "#/kit/address.server";
import { audit } from "#/kit/audit.server";${email ? '\nimport { codeAllowed } from "#/kit/limit";\nimport { log } from "#/kit/log.server";\nimport { mailConfigured, sendMail } from "#/kit/mail";' : ""}
import { w } from "#/kit/words";

/** Sign-in providers in button order; each needs its keys in the environment (see the README). */
export const PROVIDERS = ${JSON.stringify(providers)};

/** Who a session is for, as the audit log names them. */
function signedInAs(userId: string) {
  return db.select({ id: user.id, role: user.role }).from(user).where(eq(user.id, userId)).get() ?? null;
}
${allowedDomains ? `const ALLOWED_DOMAINS = ${JSON.stringify(allowedDomains.map((d) => d.toLowerCase()))};\n` : ""}/** These addresses become admins when they first sign in. */
const ADMINS: string[] = ${JSON.stringify(auth.admins.map((a) => a.toLowerCase()))};
${closed || email ? `const APP_NAME = ${JSON.stringify(ir.app.name)};\n` : ""}
const socialProviders = {
${providers
  .filter((p) => p !== "email")
  .map(provider)
  .join("\n")}
};

/** The providers whose keys are set${email ? " (email needs none: its codes go out by mail)" : ""}. */
export const configuredProviders = () => PROVIDERS.filter((p) => ${email ? 'p === "email" || ' : ""}p in socialProviders);
${
  email
    ? `
/** Whether sign-in codes can leave the machine: mail settings, or development's outbox. */
export const codesReachPeople = () => import.meta.env.DEV || mailConfigured();
/** A mail stays in the outbox (the preview, or an app without mail settings): pages say so. */
export const mailKept = () => !mailConfigured();
`
    : ""
}${
  invitations
    ? `
/** The invitation for an address, if there is one (it may have expired). */
function invitationOf(email: string) {
  return db.select().from(invitation).where(eq(invitation.email, email)).get();
}

/** The invitation for an address that is still open. */
function openInvitation(email: string) {
  const invited = invitationOf(email);
  return invited && invited.expiresAt.getTime() > Date.now() ? invited : undefined;
}
`
    : ""
}${
  refuses
    ? `
/** Why an address may not have an account here, or nothing when it may. */
function joinRefusal(email: string): string | undefined {
  // The admins may always sign in, whatever the domains or the invitations say.
  if (ADMINS.includes(email)) return undefined;${domainCheck}${invitationCheck}
  return undefined;
}
`
    : ""
}

/**
 * A demo (DEMO_SIGN_IN=1 in the environment): the sign-in page offers every role without a
 * provider, as development does, and the data is reset by whoever runs the demo. Never set it
 * on a real app.
 */
export const demoSignIn = process.env.DEMO_SIGN_IN === "1";

const NO_TOKENS = {
  accessToken: null,
  refreshToken: null,
  idToken: null,
  accessTokenExpiresAt: null,
  refreshTokenExpiresAt: null,
};

// Production needs both: without a secret sessions could be forged, without the address
// sign-in breaks. Better to refuse to start than to run like that.
if (!import.meta.env.DEV && (!process.env.BETTER_AUTH_SECRET || !process.env.BETTER_AUTH_URL))
  throw new Error("Set BETTER_AUTH_SECRET and BETTER_AUTH_URL: in production the app does not start without them.");

/** The app is served over https: its cookies can take the __Host- prefix, which needs Secure. */
const hostCookies = (process.env.BETTER_AUTH_URL ?? "").startsWith("https://");

export const auth = betterAuth({
  // In development the app runs on port 3000 (pnpm dev); set BETTER_AUTH_URL in production.
  baseURL: process.env.BETTER_AUTH_URL ?? (import.meta.env.DEV ? "http://localhost:3000" : undefined),
  // In development the app may run on any local port (the preview, the tests).
  ...(import.meta.env.DEV ? { trustedOrigins: ["http://localhost:*", "http://127.0.0.1:*"] } : {}),
  database: drizzleAdapter(db, { provider: "sqlite", schema: { account, session, user, verification } }),
  socialProviders,
  // Its limits count per address from the one header the auth route sets (src/kit/address.server.ts),
  // never from an X-Forwarded-For the visitor could make up.
  // Over https the cookies are named so only this app's own address can set them (__Host-: Secure,
  // Path=/, no Domain), not a sibling app on the same domain.
  advanced: {
    ipAddress: { ipAddressHeaders: [ADDRESS_HEADER] },
    ...(hostCookies
      ? {
          useSecureCookies: false,
          // Every other cookie it makes stays Secure too (a sign-in's state).
          defaultCookieAttributes: { secure: true },
          cookies: Object.fromEntries(
            ["session_token", "session_data", "dont_remember", "state"].map((name) => [
              name,
              { name: \`__Host-better-auth.\${name}\`, attributes: { secure: true } },
            ]),
          ),
        }
      : {}),
  },
  // On in every production build, not only where NODE_ENV says so (Better Auth's default).
  rateLimit: { enabled: !import.meta.env.DEV },
  // Email and password only serve the development sign-in; production builds leave it off.
  emailAndPassword: { enabled: import.meta.env.DEV || demoSignIn },
  user: {
    additionalFields: {
      role: { type: "string", required: true, defaultValue: ${JSON.stringify(auth.defaultRole)}, input: false },
    },
  },
  databaseHooks: {
    user: {
      create: {
        before: async (newUser) => {
          const email = newUser.email.toLowerCase();${
            refuses
              ? `
          const refused = joinRefusal(email);
          if (refused) {
            audit(db, null, { action: "sign-in refused", model: "User", details: { email, reason: refused } });
            throw new APIError("FORBIDDEN", { message: refused });
          }`
              : ""
          }
          return { data: { ...newUser, role: ADMINS.includes(email) ? "admin" : ${role} } };
        },${afterCreate}
      },
    },
    // Signing in and out are in the audit log, as the person who did it.
    session: {
      create: {
        after: async (session) => audit(db, signedInAs(session.userId), { action: "signed in" }),
      },
      // A session also ends when it expires or its user is removed: only a sign-out says so.
      delete: {
        after: async (session, ctx) => {
          if (ctx?.path === "/sign-out") audit(db, signedInAs(session.userId), { action: "signed out" });
        },
      },
    },
    // The app only signs people in with a provider and never calls it afterwards, so the
    // provider's tokens are not kept: not in the database, its backups or its exports.
    account: {
      create: { before: async (account) => ({ data: { ...account, ...NO_TOKENS } }) },
      update: { before: async (account) => ({ data: { ...account, ...NO_TOKENS } }) },
    },
  },
  plugins: [${
    email
      ? `
    // Sign-in by a six-digit code by mail: good for ten minutes, five tries, stored hashed.
    emailOTP({
      otpLength: 6,
      expiresIn: 600,
      allowedAttempts: 5,
      storeOTP: "hashed",
      async sendVerificationOTP({ email, otp, type }, ctx) {
        // Without mail settings a production app keeps no codes: nobody would get them.
        if (type !== "sign-in" || !codesReachPeople()) return;
        const address = email.toLowerCase();
        // Too many codes for the address (or from the network address): no mail. The plugin sends
        // in the background, so the page's answer is the same either way.
        try {
          codeAllowed(address, ctx?.request?.headers ?? new Headers());
        } catch {
          return;
        }
${
  refuses
    ? `        // Who may not join gets no mail, and the page says the same either way.
        const known = db.select({ id: user.id }).from(user).where(eq(user.email, address)).get();
        if (!known && joinRefusal(address)) return;
`
    : ""
}        // Not awaited, so the answer takes as long whether or not a mail goes out.
        void sendMail({
          to: address,
          subject: w.codeSubject(APP_NAME),
          text: w.codeText(APP_NAME, \`\${otp.slice(0, 3)} \${otp.slice(3)}\`),
        }).catch((error) => log.error("A sign-in code could not be sent", { error }));
      },
    }),
    tanstackStartCookies(),
  `
      : "tanstackStartCookies()"
  }],
});
`;
}

/** The signed-in user of the current request; server-only. */
export function viewerModule(auth: AuthIR): string {
  if (!hasSignIn(auth)) {
    return `${HEADER}import type { Viewer } from "#/kit/access";

/** This app has no sign-in: every visitor is anonymous. */
export async function currentViewer(): Promise<Viewer | null> {
  return null;
}
`;
  }
  return `${HEADER}import { getRequestHeaders } from "@tanstack/react-start/server";
import type { Viewer } from "#/kit/access";
import { traceWho } from "#/kit/trace.server";
import { auth } from "#/lib/auth";

/** The signed-in user of the current request, or null; the access line names them. */
export async function currentViewer(): Promise<Viewer | null> {
  const session = await auth.api.getSession({ headers: getRequestHeaders() });
  if (!session) return null;
  const { id, name, email, role } = session.user;
  traceWho(id, role);
  return { id, name, email, role };
}
`;
}

/** Everyone who can be chosen in a User field, e.g. an account manager. */
export function usersModule(): string {
  return `${HEADER}import { createServerFn } from "@tanstack/react-start";
import { asc } from "drizzle-orm";
import { db } from "#/db";
import { user } from "#/db/schema";
import { AccessDenied } from "#/kit/access";
import { currentViewer } from "#/lib/viewer.server";

/** Choices for fields that refer to a user; for signed-in users only. */
export const userOptions = createServerFn().handler(async () => {
  if (!(await currentViewer())) throw new AccessDenied(false);
  return db.select({ value: user.id, label: user.name }).from(user).orderBy(asc(user.name)).all();
});
`;
}

/**
 * The sign-in page, with a development-only sign-in as any role. Without a page to return
 * to, signing in goes to `start` (the onboarding, when the app has one).
 */
export function signInRoute(auth: AuthIR, start = "/", invitations = false): string {
  const roles = auth.roles.map((r) => r.name);
  const email = auth.signIn !== "none" && auth.signIn.providers.includes("email");
  const codes = email ? ", codes: codesReachPeople(), kept: mailKept()" : "";
  const options = invitations
    ? `
/** The sign-in choices, and whom an invitation link is for (by its token; never signs anyone in). */
const signInOptions = createServerFn()
  .validator((data: unknown) => ({ invite: text((data as Search | null)?.invite, 100) }))
  .handler(({ data }) => {
    const providers = configuredProviders();
    const invited = data.invite
      ? db
          .select({ email: invitation.email, role: invitation.role, expiresAt: invitation.expiresAt })
          .from(invitation)
          .where(eq(invitation.token, data.invite))
          .get()
      : undefined;
    const open = invited && invited.expiresAt.getTime() > Date.now() ? invited : undefined;
    return {
      providers,
      missing: PROVIDERS.filter((p) => !providers.includes(p)),
      demo: demoSignIn,
      invitation: open ? { email: open.email, role: ROLE_LABELS[open.role] ?? open.role } : null${codes},
    };
  });
`
    : `
const signInOptions = createServerFn().handler(() => {
  const providers = configuredProviders();
  return { providers, missing: PROVIDERS.filter((p) => !providers.includes(p)), demo: demoSignIn${codes} };
});
`;
  return `${HEADER}import { createFileRoute, useRouter } from "@tanstack/react-router";
import { createServerFn } from "@tanstack/react-start";
import { getRequestHeaders } from "@tanstack/react-start/server";
import { eq } from "drizzle-orm";
import { db } from "#/db";
import { ${invitations ? "invitation, user" : "user"} } from "#/db/schema";
import { oneOf, optional, type Search, shaped${invitations ? ", text" : ""} } from "#/kit/params";
import { app } from "#/generated/app";
import { SignIn } from "#/kit/SignIn";
import { w } from "#/kit/words";
import { auth, ${email ? "codesReachPeople, " : ""}configuredProviders, demoSignIn, ${email ? "mailKept, " : ""}PROVIDERS } from "#/lib/auth";
import { authClient } from "#/lib/auth-client";

const ROLES = ${JSON.stringify(roles)} as const;
${invitations ? `const ROLE_LABELS: Record<string, string> = ${record(roleLabels(auth))};\n` : ""}${options}
/** Development, or a demo: signs in as a user with the role, without a provider. */
const devSignIn = createServerFn({ method: "POST" })
  .validator((role: unknown) => {
    const known = oneOf(role, ROLES);
    if (!known) throw new Error("No such role.");
    return known;
  })
  .handler(async ({ data: role }) => {
    if (!import.meta.env.DEV && !demoSignIn) throw new Error(w.developmentOnlyNote);
    const prefix = demoSignIn && !import.meta.env.DEV ? "demo" : "dev";
    const email = \`\${prefix}-\${role}@${devDomain(auth)}\`;
    const password = \`\${prefix}-password\`;
    const made = () => db.select({ id: user.id }).from(user).where(eq(user.email, email)).get();
    if (!made()) {
      // Two tabs signing in at once (Studio and its guide): the other may make the user first.
      await auth.api
        .signUpEmail({ body: { email, password, name: \`\${prefix === "demo" ? "Demo" : "Dev"} \${role}\` } })
        .catch((error) => {
          if (!made()) throw error;
        });
    }
    db.update(user).set({ role }).where(eq(user.email, email)).run();
    await auth.api.signInEmail({ body: { email, password }, headers: getRequestHeaders() });
  });

export const Route = createFileRoute("/sign-in")({
  // Only paths within the app, so the page cannot send anyone elsewhere.
  validateSearch: (s: Search) => optional({
    redirect: shaped(s.redirect, /^\\/(?!\\/)/),${
      invitations
        ? `
    invite: text(s.invite, 100),`
        : ""
    }
  }),${
    invitations
      ? `
  loaderDeps: ({ search }) => ({ invite: search.invite }),
  loader: ({ deps }) => signInOptions({ data: { invite: deps.invite } }),`
      : `
  loader: () => signInOptions(),`
  }
  component: SignInPage,
});

function SignInPage() {
  const { providers, missing, demo${invitations ? ", invitation" : ""}${email ? ", codes, kept" : ""} } = Route.useLoaderData();
  const { redirect = ${JSON.stringify(start)} } = Route.useSearch();
  const router = useRouter();
  return (
    <SignIn
      appName={app.name}
      providers={providers}
      missing={missing}${invitations ? "\n      invitation={invitation}" : ""}${
        // Only invited people may sign in: the page says so before anyone waits for a code.
        invitations && auth.signIn !== "none" && !auth.signIn.selfSignUp
          ? "\n      invitedOnly"
          : ""
      }
      devRoles={import.meta.env.DEV || demo ? [...ROLES] : undefined}
      demo={demo}
      onProvider={async (provider) => {
        const { error } = await authClient.signIn.social({ provider, callbackURL: redirect });
        if (error) throw new Error(error.message);
      }}${
        email
          ? `
      codes={codes}
      kept={kept}
      onSendCode={async (address) => {
        const { error } = await authClient.emailOtp.sendVerificationOtp({ email: address, type: "sign-in" });
        if (error) throw new Error(error.message);
      }}
      onCode={async (address, code) => {
        const { error } = await authClient.signIn.emailOtp({ email: address, otp: code.replace(/\\s/g, "") });
        if (error) throw new Error(error.message);
        await router.invalidate();
        await router.navigate({ href: redirect });
      }}`
          : ""
      }
      onDevRole={async (role) => {
        await devSignIn({ data: role as (typeof ROLES)[number] });
        await router.invalidate();
        await router.navigate({ href: redirect });
      }}
    />
  );
}
`;
}

/** Who is invited, with which role, until when; accepted invitations are deleted. */
const INVITATION_TABLE = `
export const invitation = sqliteTable("invitation", {
  id: text().primaryKey(),
  email: text().notNull().unique(),
  role: text().notNull(),
  token: text().notNull().unique(),
  invitedById: text().references(() => user.id, { onDelete: "set null" }),
  createdAt: integer({ mode: "timestamp_ms" }).notNull().$defaultFn(() => new Date()),
  expiresAt: integer({ mode: "timestamp_ms" }).notNull(),
});`;

/** Better Auth's tables, as its CLI would generate them, plus each user's role. */
export function authTables(auth: AuthIR, invitations = false): string {
  return `${betterAuthTables(auth)}${invitations ? `\n${INVITATION_TABLE}` : ""}`;
}

function betterAuthTables(auth: AuthIR): string {
  return `export const user = sqliteTable("user", {
  id: text().primaryKey(),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: integer({ mode: "boolean" }).default(false).notNull(),
  image: text(),
  role: text().notNull().default(${JSON.stringify(auth.defaultRole)}),
  createdAt: integer({ mode: "timestamp_ms" }).notNull().$defaultFn(() => new Date()),
  updatedAt: integer({ mode: "timestamp_ms" })
    .notNull()
    .$defaultFn(() => new Date())
    .$onUpdate(() => new Date()),
});

export const session = sqliteTable(
  "session",
  {
    id: text().primaryKey(),
    expiresAt: integer({ mode: "timestamp_ms" }).notNull(),
    token: text().notNull().unique(),
    createdAt: integer({ mode: "timestamp_ms" }).notNull(),
    updatedAt: integer({ mode: "timestamp_ms" }).notNull(),
    ipAddress: text(),
    userAgent: text(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (t) => [index("session_user_id_idx").on(t.userId)],
);

export const account = sqliteTable(
  "account",
  {
    id: text().primaryKey(),
    accountId: text().notNull(),
    providerId: text().notNull(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: integer({ mode: "timestamp_ms" }),
    refreshTokenExpiresAt: integer({ mode: "timestamp_ms" }),
    scope: text(),
    password: text(),
    createdAt: integer({ mode: "timestamp_ms" }).notNull(),
    updatedAt: integer({ mode: "timestamp_ms" }).notNull(),
  },
  (t) => [index("account_user_id_idx").on(t.userId)],
);

export const verification = sqliteTable(
  "verification",
  {
    id: text().primaryKey(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: integer({ mode: "timestamp_ms" }).notNull(),
    createdAt: integer({ mode: "timestamp_ms" }).notNull().$defaultFn(() => new Date()),
    updatedAt: integer({ mode: "timestamp_ms" })
      .notNull()
      .$defaultFn(() => new Date())
      .$onUpdate(() => new Date()),
  },
  (t) => [index("verification_identifier_idx").on(t.identifier)],
);`;
}

/** The README section on signing in: provider setup and the development sign-in. */
export function signInReadme(ir: SpecIR, auth: AuthIR): string {
  if (auth.signIn === "none") return "";
  const setup = auth.signIn.providers.map((p) => {
    if (p === "email")
      return `### Email

People type their address and get a six-digit code by mail, good for ten minutes and five tries. Signing in and signing up are the same form; who may sign up follows the app's sign-in settings, and anyone else is told the same and gets no mail. At most five codes an hour go to one address (and twenty to one network address): someone asking for a sixth waits. The codes go out through the app's mail settings (\`SMTP_URL\` and \`MAIL_FROM\`, see "Mail"); without them, in development, they land in \`data/mail/outbox\`, and in production the sign-in page says that it cannot send mail.`;
    const [id, secret] = ENV[p] as [string, string];
    const console =
      p === "google"
        ? "In the [Google Cloud console](https://console.cloud.google.com/apis/credentials), create an OAuth client ID of type *Web application*"
        : "In [Meta for Developers](https://developers.facebook.com/apps), create an app with *Facebook Login*";
    return `### ${humanize(p)}

1. ${console}.
2. Add the redirect URLs \`http://localhost:3000/api/auth/callback/${p}\` and \`https://<your domain>/api/auth/callback/${p}\`.
3. Put the keys in \`.env\` (never commit it):

   \`\`\`sh
   ${id}=...
   ${secret}=...
   \`\`\``;
  });
  return `
## Signing in

${ir.app.name} signs users in with ${auth.signIn.providers.map((p) => (p === "email" ? "a code by email" : humanize(p))).join(" or ")}, through [Better Auth](https://www.better-auth.com). In development, the sign-in page also lets you sign in as any role (${auth.roles.map((r) => r.name).join(", ")}) without a provider; production builds leave that out.

In production, set \`BETTER_AUTH_SECRET\` (at least 32 random characters, e.g. \`openssl rand -base64 32\`) and \`BETTER_AUTH_URL\` (the app's public address) as well.

${setup.join("\n\n")}
`;
}
